shop.yml:
# Mainplugins Shop - settings. Items and prices are in categories/<id>.yml (one file per category).
# Texts (titles, buttons, messages) are in lang/en.yml and lang/pl.yml.
# Reload without restart: /@shop reload

# Order of categories in the main menu (file names from categories/ without .yml).
categories: [blocks, farming, ores, mob-drops, food]

# How prices are rounded when a player buys part of a pack or when dynamic prices change them:
#   whole = whole coins (1 piece of a "64 for 10" pack costs 1)
#   cents = cents (1 piece of a "64 for 10" pack costs 0.16)
price-rounding: cents

# Sell prices react to what players sell: lots of selling -> the price drops, nobody sells -> it rises.
dynamic-prices:
  enabled: true
  cycle-minutes: 60        # how often prices are recalculated
  min-multiplier: 0.5      # lowest sell price = 50% of the normal one
  max-multiplier: 1.5      # highest sell price = 150% of the normal one
  reset-days: 14           # every N days all prices go back to normal
  max-sell-share: 0.9      # selling never pays more than 90% of the buy price

# Sales statistics (stats.yml + stats.csv for Excel) with hints which prices to change.
stats:
  enabled: false

# Where things are in each window. size = 9, 18, 27, 36, 45 or 54.
# Roles: CATEGORY_SLOT (main menu), ITEM_SLOT, AMOUNT_SLOT (buy-picker, amount = pieces),
#        NAV_BACK, NAV_PREV, NAV_NEXT, EXIT, SEARCH, SORT, FILLER (optional material).
